import { randomUUID } from "node:crypto";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { KnowledgeLintReportSchema, WikiLintReceiptSchema, WikiResultSchema, type WikiRevision, type WikiSourceRevision } from "../packages/contracts/src/index";
import {createRequire} from "node:module";
const Database = createRequire(new URL("../packages/infrastructure/package.json", import.meta.url))("better-sqlite3");
import { afterEach, expect, it } from "vitest";
import { SqliteWorkspaceRepository } from "../packages/infrastructure/src/index";
const NOW="2026-10-27T00:00:00.000Z", LATER="2026-10-27T00:00:02.000Z";
const valid={status:"confirmed" as const,validFrom:null,validUntil:null};
const dispose:(()=>void)[]=[];
afterEach(()=>{for(const close of dispose.splice(0).reverse())close();});
const command=(method:string,payload:unknown)=>({schemaVersion:1,requestId:randomUUID(),idempotencyKey:randomUUID(),method,payload});
function data(input:unknown){const r=WikiResultSchema.parse(input);if(!r.ok)throw Error(r.error.message);return r.data;}
async function fixture(expires:string|null=null){
 const dir=mkdtempSync(join(tmpdir(),"c-p1-probe-"));dispose.push(()=>rmSync(dir,{recursive:true,force:true}));
 const file=join(dir,"synthetic.sqlite"),repo=new SqliteWorkspaceRepository(file);dispose.push(()=>repo.close());
 repo.commit(command("workspace.create",{name:"合成P1边界"}) as never,{actorId:"synthetic-human",origin:"human_ui"});
 const context={workspaceId:repo.read()!.id,actorId:"synthetic-human",origin:"human_ui" as const,now:NOW};
 const payload={sourceId:randomUUID(),expectedVersion:0,label:"合成资料",sourceStatus:"synthetic",mediaType:"text/plain",sourceText:"Synthetic source",acquiredAt:NOW,sourceUri:null,permissionNote:"synthetic only",validity:{...valid,validUntil:expires}};
 const sourceData=data(await repo.executeWiki(command("source.stage",payload),context));if(sourceData.kind!=="sourceRevision")throw Error("source fixture");
 const source:WikiSourceRevision=sourceData.revision,ref={referenceId:randomUUID(),sourceId:source.sourceId,sourceRevisionId:source.sourceRevisionId,sourceVersion:source.version,artifactHash:source.artifactHash,location:{kind:"text",start:0,end:source.sourceText.length},excerptHash:source.artifactHash,assertion:"fact"};
 const markdown="# Synthetic candidate",sectionId=randomUUID();
 const wiki=data(await repo.executeWiki(command("wiki.stage",{documentId:randomUUID(),expectedVersion:0,parentRevisionId:null,content:{kind:"sop",title:"合成知识",locale:"en",scope:{platforms:[],markets:[],categories:[]},markdown,validity:valid,sections:[{sectionId,title:"合成段落",location:{kind:"text",start:0,end:markdown.length},sourceReferenceIds:[ref.referenceId]}],sourceRefs:[ref],relations:[],rules:[]}}),context));
 if(wiki.kind!=="wikiRevision")throw Error("wiki fixture"); const revision:WikiRevision=wiki.record.revision;
 const db=new Database(file);dispose.push(()=>db.close());
 const binding={revisionId:revision.revisionId,contentHash:revision.contentHash,sourceSetHash:revision.sourceSetHash};
 return {repo,db,context,revision,source,payload,binding,async approve(){const receipt=repo.runWikiLint(revision.revisionId,context)!; const cmd=command("wiki.review",{...binding,expectedLifecycleVersion:1,decision:"approve",note:"synthetic technical review",lintReceiptId:receipt.receiptId});const result=await repo.executeWiki(cmd,context);const d=data(result);if(d.kind!=="wikiRevision"||!d.record.lifecycle.review)throw Error("review fixture");return {receipt,cmd,result,reviewId:d.record.lifecycle.review.reviewId};}};
}

import { KnowledgeMaintenanceResultSchema, MaintenanceExchangeSchema } from "../packages/contracts/src/index";
const readCommand=(method:string,payload:unknown)=>({schemaVersion:1,requestId:randomUUID(),method,payload});
async function maint(f:Awaited<ReturnType<typeof fixture>>,method:string,payload:unknown,cmd?:any){return KnowledgeMaintenanceResultSchema.parse(await f.repo.executeWikiMaintenance(cmd??(method.startsWith("wiki.get")?readCommand(method,payload):command(method,payload)),f.context));}
const target=(f:Awaited<ReturnType<typeof fixture>>)=>({kind:"source",sourceId:f.source.sourceId,sourceRevisionId:f.source.sourceRevisionId,artifactHash:f.source.artifactHash});
const subject=(f:Awaited<ReturnType<typeof fixture>>)=>({target:target(f),reason:"withdrawn",replacementRevisionId:null});
const withdraw=(f:Awaited<ReturnType<typeof fixture>>)=>({sourceRevisionId:f.source.sourceRevisionId,expectedLifecycleVersion:1,note:"Synthetic withdrawal"});
function counts(f:Awaited<ReturnType<typeof fixture>>){return Object.fromEntries(["knowledge_source","knowledge_maintenance_issue","knowledge_impact_report","knowledge_impact_item","knowledge_index_status","knowledge_index_rebuild","knowledge_seq","outbox","idempotency"].map(t=>[t,f.db.prepare(`SELECT * FROM ${t} ORDER BY rowid`).all()]));}
function ok(r:any,kind:string){expect(r.ok).toBe(true);if(!r.ok||r.data.kind!==kind)throw Error(JSON.stringify(r));return r.data;}

it("event evidence: returned withdrawal event should resolve its own issue if supported as execution evidence",async()=>{const f=await fixture();const x=ok(await maint(f,"source.withdraw",withdraw(f)),"sourceWithdrawal");const p=ok(await maint(f,"wiki.getMaintenance",{kinds:[],states:[],limit:10,cursor:null}),"maintenancePage").page;const before=counts(f);const result=await maint(f,"wiki.resolveMaintenance",{issueId:p.issues[0].issueId,expectedIssueVersion:1,action:"resolve",note:"Synthetic withdrawal evidence",evidenceIds:[x.event.eventId]});console.log("C_EVENT_EVIDENCE",JSON.stringify({returnedEventId:x.event.eventId,result,unchanged:JSON.stringify(before)===JSON.stringify(counts(f))}));expect(result.ok).toBe(true);});
it("event persistence control: saved replay contains full original event and outbox references it",async()=>{const f=await fixture();const cmd=command("source.withdraw",withdraw(f));const first=ok(await maint(f,cmd.method,cmd.payload,cmd),"sourceWithdrawal");const saved=f.db.prepare("SELECT result_json FROM idempotency WHERE key=?").get(cmd.idempotencyKey) as any;expect(JSON.parse(saved.result_json).data.event).toEqual(first.event);const rows=f.db.prepare("SELECT payload_json FROM outbox WHERE type='source.withdrawn'").all() as any[];expect(rows.map(r=>JSON.parse(r.payload_json).eventId)).toContain(first.event.eventId);expect(await f.repo.executeWikiMaintenance({...cmd,requestId:randomUUID()},{...f.context,now:LATER})).toEqual(JSON.parse(saved.result_json));});
